from collections.abc import AsyncIterator
from contextlib import asynccontextmanager

@asynccontextmanager
async def lifespan(server: MCPServer) -&gt; AsyncIterator[dict]:
    pool = await open_pool()
    try:
        yield {"pool": pool}
    finally:
        await pool.close()

